type Split<T> = (input: T) => [T, T] | null;      // null = base case
type Combine<R> = (left: R, right: R) => R;

export function solve<T, R>(
  input: T, split: Split<T>, leaf: (t: T) => R, combine: Combine<R>,
): R {
  const parts = split(input);
  return parts
    ? combine(solve(parts[0], split, leaf, combine),   // fork + join
              solve(parts[1], split, leaf, combine))
    : leaf(input);                                     // base case
}
